WITH parsed AS (SELECT id, customer_id, created_at, ship_to.zip AS ship_zip, AGGREGATE(items, 0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS basket_amount, attributes['device'] AS device, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts) SELECT id, customer_id, created_at, ship_zip, basket_amount, device, coupons_text, LEAD(basket_amount, 2) OVER (ORDER BY created_at, id) AS next_basket_amount, SUM(basket_amount) OVER w_running AS cumulative_basket_amount, ROW_NUMBER() OVER w_part AS row_seq, MAX(basket_amount) OVER (PARTITION BY customer_id) AS customer_id_max_basket_amount, AVG(basket_amount) OVER (PARTITION BY customer_id ORDER BY basket_amount, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS basket_amount_avg_3_prior FROM parsed WINDOW w_running AS (PARTITION BY customer_id ORDER BY basket_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (ORDER BY basket_amount, id);
